Arguments: {"title":"Inspect visible reviews in list","cwd":null,"code":"const tabId = 118779795;
const reviewsData = await browserjs(tabId, () => {
  const listItems = Array.from(document.querySelectorAll('ul.rec-reviews-list li, [role="listitem"]'));
  return listItems.map(li => {
    const heading = li.querySelector('h3, [role="heading"]')?.textContent?.trim();
    const stars = li.querySelector('.sarsa-rating-stars-wrapper, [aria-label*="star"]')?.getAttribute('aria-label') || li.textContent.match(/\d out of 5 stars/)?.[0];
    const text = li.querySelector('p, .rec-review-body')?.textContent?.trim();
    const showMoreBtn = Array.from(li.querySelectorAll('button')).find(b => b.textContent.includes('Show More'));
    const helpful = Array.from(li.querySelectorAll('button')).find(b => b.textContent.includes('Yes'))?.textContent?.trim();
    return {
      heading,
      stars,
      text,
      hasShowMore: !!showMoreBtn,
      helpful
    };
  });
});
console.log("Reviews data:", JSON.stringify(reviewsData, null, 2));
"}
